      "claim": "Performance metrics are social constructs and must be redefined to prioritize worker agency over mere processing speed.",
      "targets": ["AN-37"]
    },
    {
      "claim": "A framework that avoids democratic friction by design is not a stable governance model.",
      "targets": ["AN-35"]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Democratic stakeholders are capable of accurately assessing the long-term impact of AI systems on their own professional agency.",
      "if_wrong": "If stakeholders cannot accurately predict these impacts, regional boards might exercise veto power in ways that stifle beneficial innovation without actually protecting labor."
    }
  ],
  "disagreement_type": "VALUES"
}

